/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';

const history = [], display = [], queue = [], notices = [], deltas = [];
const pending = new Map();
const feed = createProgressFeed({ initialPacket: 'initial', decode: packet => packet === 'initial' ? { value: 0 } : new Promise(resolve => pending.set(packet, resolve)) });
const stopTelemetry = collectProgressTelemetry(feed, frame => deltas.push(frame));
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record: x => queue.push(x), showQueued: x => notices.push(x), recordProgress: x => history.push(x), showProgress: x => display.push(x) });
const file = { id: 'a', progressFeed: feed };
workspace.select(file);
assert.deepEqual(display.map(x => x.frame), [{ value: 0 }]);
assert.deepEqual(deltas, []);
feed.emit('older');
feed.emit('newer');
pending.get('newer')({ value: 2 });
await Promise.resolve();
pending.get('older')({ value: 1 });
await Promise.resolve();
assert.deepEqual(display.map(x => x.frame.value), [0, 2]);
assert.deepEqual(history.map(x => x.frame.value), [0, 2, 1]);
assert.deepEqual(deltas.map(x => x.value), [2, 1]);
assert.deepEqual(queue.map(x => x.kind), ['select']);
assert.equal(notices.length, 1);
workspace.hide();
feed.emit('after-hide');
assert.equal(pending.has('after-hide'), true);
pending.get('after-hide')({ value: 3 });
await Promise.resolve();
assert.equal(display.length, 2);
workspace.select(file);
assert.deepEqual(display.map(x => x.frame.value), [0, 2, 0]);
stopTelemetry();
workspace.dispose();
console.log('progress behavior checks passed');
EOF"

